#Funk #MúsicaFunk #FunkyBeats #FunkOriginal #NuevoFunk`;

const tags = "Funk, MúsicaFunk, FunkyBeats, FunkOriginal, NuevoFunk, Funk Music, Groove, Bajos potentes, Funk latino, Música funk original";

// === HASHTAG + EMOJI ALEATORIO (se agrega después del título) ===
const hashtagsPool = [
  "#FunkIndependiente", "#MúsicaFunk", "#EnergíaFunk",
  "#MotivaciónFunk", "#FunkVibes", "#GrooveIndependiente",
  "#NuevaMusica", "#FunkEnergetico", "#FunkMotivador",
  "#IndieFunk", "#MúsicaOriginal", "#FunkCreaciones"
];
const randomHashtag = hashtagsPool[Math.floor(Math.random() * hashtagsPool.length)];

const emojis = ["🔥", "⚡", "💪", "🚀", "🌀", "🌟", "🎧", "❤️", "😎", "💥", "🎉", "🔥"];
const randomEmoji = emojis[Math.floor(Math.random() * emojis.length)];

// === ACTIVACIÓN - DEVOLVER TODO ===
return $input.all().map(item => {
  return {
    json: {
      ...item.json,
      description: description,
      tags: tags,

      // Nuevo: hashtag + emoji aleatorio después del título
      hashtags: randomHashtag,
      emojis: randomEmoji
    },
    binary: item.binary
  };
});

